/// A member discovered by walking a ustar stream in header/apply order.
pub struct Row {
    pub name: String,
    pub hdr: u64,
    pub size: u64,
    pub body: u64,
    pub flag: u8,
}

fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let field = buf
        .iter()
        .copied()
        .skip_while(|b| *b == b' ' || *b == 0)
        .take_while(|b| *b != b' ' && *b != 0)
        .collect::<Vec<_>>();
    if field.is_empty() || field.iter().any(|b| !(b'0'..=b'7').contains(b)) {
        return Err(1);
    }
    let mut n = 0u64;
    for b in field {
        n = n.checked_mul(8).and_then(|x| x.checked_add(u64::from(b - b'0'))).ok_or(1)?;
    }
    Ok(n)
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 512 {
        return Err(1);
    }
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut ended = false;
    while off.checked_add(512).ok_or(1)? <= raw.len() {
        let blk = &raw[off..off + 512];
        if blk.iter().all(|b| *b == 0) {
            ended = true;
            break;
        }
        if &blk[257..262] != b"ustar" {
            return Err(1);
        }
        let size = oct_u64(&blk[124..136])?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let next = (off as u64).checked_add(512).and_then(|x| x.checked_add(padded)).ok_or(1)?;
        if next > raw.len() as u64 {
            return Err(1);
        }
        let nlen = blk[..100].iter().position(|b| *b == 0).unwrap_or(100);
        let name = String::from_utf8(blk[..nlen].to_vec()).map_err(|_| 1)?;
        rows.push(Row {
            name,
            hdr: off as u64,
            size,
            body: (off + 512) as u64,
            flag: blk[156],
        });
        off = next as usize;
    }
    if !ended || rows.is_empty() {
        return Err(1);
    }
    Ok(rows)
}
