pub struct Pack {
    pub t: String,
    pub c: String,
    pub e: Vec<String>,
    pub n: u32,
    pub s: String,
    pub w: String,
}

struct Rec { name: String, size: u64, body: u64 }

fn read_idx(path: &str) -> Result<Vec<Rec>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 9 || &raw[..5] != b"SILT1" { return Err(1); }
    let n = u32::from_le_bytes(raw[5..9].try_into().map_err(|_| 1)?) as usize;
    let mut i = 9usize;
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        if i.checked_add(26).ok_or(1)? > raw.len() { return Err(1); }
        let _hdr = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let size = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let body = u64::from_le_bytes(raw[i..i+8].try_into().map_err(|_| 1)?); i += 8;
        let nl = u16::from_le_bytes(raw[i..i+2].try_into().map_err(|_| 1)?) as usize; i += 2;
        if i.checked_add(nl).ok_or(1)? > raw.len() { return Err(1); }
        let name = String::from_utf8(raw[i..i+nl].to_vec()).map_err(|_| 1)?; i += nl;
        out.push(Rec { name, size, body });
    }
    if i != raw.len() { return Err(1); }
    Ok(out)
}

fn digest(text: &str) -> Result<String, i32> {
    use std::io::Write;
    let mut child = std::process::Command::new("python3")
        .args(["-c", "import hashlib,sys;print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())"])
        .stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped())
        .spawn().map_err(|_| 1)?;
    child.stdin.as_mut().ok_or(1)?.write_all(text.as_bytes()).map_err(|_| 1)?;
    drop(child.stdin.take());
    let result = child.wait_with_output().map_err(|_| 1)?;
    if !result.status.success() { return Err(1); }
    let s = String::from_utf8(result.stdout).map_err(|_| 1)?.trim().to_string();
    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { return Err(1); }
    Ok(s)
}

pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let recs = read_idx(b)?;
    let archive = std::fs::read(a).map_err(|_| 1)?;
    let mut timezone = String::new();
    let mut cluster = String::new();
    let mut events = std::collections::BTreeSet::new();
    let mut names = Vec::with_capacity(recs.len());
    for r in &recs {
        let start = usize::try_from(r.body).map_err(|_| 1)?;
        let len = usize::try_from(r.size).map_err(|_| 1)?;
        let end = start.checked_add(len).ok_or(1)?;
        if end > archive.len() { return Err(1); }
        let blob = &archive[start..end];
        let normalized = r.name.strip_prefix("./").unwrap_or(&r.name);
        if normalized == "etc/sys.conf" {
            let map = crate::slate::kv::pairs(blob);
            if let Some(v) = map.get("timezone") { timezone = v.clone(); }
            if let Some(v) = map.get("cluster") { cluster = v.clone(); }
        } else if normalized == "var/log/app.log" {
            for line in String::from_utf8_lossy(blob).lines() {
                let event = line.trim();
                if !event.is_empty() { events.insert(event.to_string()); }
            }
        }
        names.push(r.name.clone());
    }
    let source = std::path::Path::new(a).file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack {
        t: timezone,
        c: cluster,
        e: events.into_iter().collect(),
        n: u32::try_from(recs.len()).map_err(|_| 1)?,
        s: source,
        w: digest(&names.join("\n"))?,
    })
}
